1	// The low-level HMAC functions (HMAC_CTX_new/HMAC_Init_ex/HMAC_Update/
2	// HMAC_Final) are available in both OpenSSL 1.1.1 and OpenSSL 3.x.
3	// OpenSSL 3.x marks them deprecated in favour of the EVP_MAC interface
4	// (which 1.1.1 does not have); suppress those deprecation warnings so the
5	// portable interface builds cleanly on 3.x. The streaming Init/Update/
6	// Final form lets the message file be digested in fixed-size chunks
7	// instead of being held in memory all at once.
8	#define OPENSSL_SUPPRESS_DEPRECATED
9	#include <openssl/evp.h>
10	#include <openssl/hmac.h>
11	
12	#include <array>
13	#include <cstddef>
14	#include <fstream>
15	#include <iostream>
16	#include <map>
17	#include <memory>
18	#include <string>
19	#include <string_view>
20	#include <vector>
21	
22	namespace {
23	
24	constexpr std::string_view kTagUsage =
25	    "Usage: messagetag tag --key-hex <hex-key> --file <message-file>\n";
26	
27	constexpr std::string_view kVerifyUsage =
28	    "Usage: messagetag verify --key-hex <hex-key> --file <message-file> "
29	    "--tag-hex <hex-tag>\n";
30	
31	// SHA-256 HMAC tags are always 32 bytes / 64 hex characters.
32	constexpr std::size_t kTagBytes = 32;
33	
34	// Decode hexadecimal into raw bytes: every two characters are one byte and
35	// leading zeros must be preserved (e.g. "0001" is two bytes, not the number
36	// 1). Only digits and a-f/A-F are accepted; empty input, odd length,
37	// whitespace and a 0x prefix are rejected.
38	bool decodeHex(std::string_view hex, std::vector<unsigned char>& bytes) {
39	    if (hex.empty() || hex.size() % 2 != 0) {
40	        return false;
41	    }
42	    auto nibble = [](char c) -> int {
43	        if (c >= '0' && c <= '9') return c - '0';
44	        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
45	        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
46	        return -1;
47	    };
48	    bytes.clear();
49	    bytes.reserve(hex.size() / 2);
50	    for (std::size_t i = 0; i < hex.size(); i += 2) {
51	        int hi = nibble(hex[i]);
52	        int lo = nibble(hex[i + 1]);
53	        if (hi < 0 || lo < 0) {
54	            return false;
55	        }
56	        bytes.push_back(static_cast<unsigned char>((hi << 4) | lo));
57	    }
58	    return true;
59	}
60	
61	std::string hexEncode(const unsigned char* data, std::size_t length) {
62	    static constexpr char kHex[] = "0123456789abcdef";
63	    std::string out;
64	    out.resize(length * 2);
65	    for (std::size_t i = 0; i < length; ++i) {
66	        out[2 * i] = kHex[data[i] >> 4];
67	        out[2 * i + 1] = kHex[data[i] & 0x0F];
68	    }
69	    return out;
70	}
71	
72	// Parse options of the form "--name value" starting at argv[2]. On a usage
73	// problem (an unknown argument, or an option without a following value) a
74	// command-specific diagnostic and the usage line are written to stderr and
75	// this returns false; the caller then exits with code 2. On success the
76	// collected values are stored keyed by option name, and the caller checks
77	// which required options are present. Only the value-taking options named
78	// in `names` are accepted.
79	//
80	// An option's value is missing not only when nothing follows it, but also
81	// when the next token is itself one of this command's option names: in
82	// "--file --file" the second "--file" is another option, not a file name,
83	// so the first "--file" is reported as missing a value instead of
84	// consuming the option as its value. Only an exact match with a recognized
85	// option name triggers this; any other token (including one that merely
86	// starts with a dash, such as "--notes", and including an explicitly empty
87	// string) is taken as the value, so file paths with leading dashes stay
88	// usable and empty values keep their own distinct diagnostics.
89	bool parseValueOptions(int argc, char* argv[], std::string_view command,
90	                       std::string_view usage,
91	                       const std::vector<std::string_view>& names,
92	                       std::map<std::string, std::string>& values) {
93	    auto isOptionName = [&names](std::string_view arg) {
94	        for (std::string_view name : names) {
95	            if (arg == name) {
96	                return true;
97	            }
98	        }
99	        return false;
100	    };
101	    for (int i = 2; i < argc; ++i) {
102	        std::string arg(argv[i]);
103	        if (!isOptionName(arg)) {
104	            std::cerr << "messagetag " << command
105	                      << ": error: unknown argument '" << arg << "'\n"
106	                      << usage;
107	            return false;
108	        }
109	        // The diagnostic names only the option that lacks a value; the
110	        // following token (a recognized option name, or nothing at all) is
111	        // never spliced into the message, and neither is any key or tag
112	        // material supplied elsewhere on the command line.
113	        if (i + 1 >= argc || isOptionName(argv[i + 1])) {
114	            std::cerr << "messagetag " << command
115	                      << ": error: option '" << arg
116	                      << "' requires a value\n"
117	                      << usage;
118	            return false;
119	        }
120	        values[arg] = argv[++i];
121	    }
122	    return true;
123	}
124	
125	bool requireOption(const std::map<std::string, std::string>& values,
126	                   std::string_view command, std::string_view usage,
127	                   std::string_view name) {
128	    if (values.find(std::string(name)) == values.end()) {
129	        std::cerr << "messagetag " << command
130	                  << ": error: missing required option '" << name << "'\n"
131	                  << usage;
132	        return false;
133	    }
134	    return true;
135	}
136	
137	// Decode the --key-hex argument, emitting the shared key-format diagnostic
138	// (which never echoes the submitted key) on failure.
139	bool parseKey(std::string_view command, std::string_view usage,
140	              const std::string& keyHex, std::vector<unsigned char>& key) {
141	    if (decodeHex(keyHex, key)) {
142	        return true;
143	    }
144	    std::cerr << "messagetag " << command
145	              << ": error: invalid --key-hex: expected a non-empty, "
146	                 "even-length string of hexadecimal characters (0-9, a-f, A-F); "
147	                 "every two characters denote one key byte and leading zeros must "
148	                 "be kept; a 0x prefix and whitespace are not accepted\n"
149	              << usage;
150	    return false;
151	}
152	
153	// Stream the message file into HMAC-SHA-256 a fixed-size chunk at a time.
154	// The message is never stored whole: regardless of file length, only one
155	// 64 KiB read buffer is needed on top of the constant-size HMAC context.
156	//
157	// The bytes are not interpreted as text: the file is opened in binary mode,
158	// trailing newlines are kept, line endings are not converted and zero bytes
159	// are preserved. An empty file simply yields no Update calls, which
160	// authenticates the empty message.
161	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
162	
163	HmacStatus hmacSha256File(const std::vector<unsigned char>& key,
164	                          const std::string& path,
165	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
166	                          std::size_t& macLength) {
167	    HMAC_CTX* rawCtx = HMAC_CTX_new();
168	    if (rawCtx == nullptr) {
169	        return HmacStatus::kCryptoError;
170	    }
171	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx(rawCtx,
172	                                                            HMAC_CTX_free);
173	
174	    // Init with the key and SHA-256. HMAC_Init_ex performs the standard
175	    // RFC 2104 key normalization itself, so keys longer than the SHA-256
176	    // block size are hashed exactly as the standard requires; the resulting
177	    // tag is identical to the one-shot HMAC() interface on both OpenSSL
178	    // 1.1.1 and OpenSSL 3.x. The key is validated to be non-empty before
179	    // this is called, so key.data() is always valid.
180	    if (HMAC_Init_ex(ctx.get(), key.data(), static_cast<int>(key.size()),
181	                     EVP_sha256(), nullptr) != 1) {
182	        return HmacStatus::kCryptoError;
183	    }
184	
185	    std::ifstream in(path, std::ios::binary | std::ios::in);
186	    if (!in) {
187	        return HmacStatus::kReadError;
188	    }
189	
190	    std::array<char, 65536> buffer{};
191	    while (in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()))) {
192	        if (HMAC_Update(ctx.get(),
193	                        reinterpret_cast<const unsigned char*>(buffer.data()),
194	                        static_cast<std::size_t>(in.gcount())) != 1) {
195	            return HmacStatus::kCryptoError;
196	        }
197	    }
198	    // A read error (including one that happens after part of the message has
199	    // already been fed to HMAC) aborts authentication: Final is never called,
200	    // so no partial-message tag can be produced. EOF with a short final read
201	    // is normal and those remaining bytes must still participate.
202	    if (in.bad()) {
203	        return HmacStatus::kReadError;
204	    }
205	    if (in.gcount() > 0) {
206	        if (HMAC_Update(ctx.get(),
207	                        reinterpret_cast<const unsigned char*>(buffer.data()),
208	                        static_cast<std::size_t>(in.gcount())) != 1) {
209	            return HmacStatus::kCryptoError;
210	        }
211	    }
212	
213	    unsigned int outLength = 0;
214	    if (HMAC_Final(ctx.get(), mac.data(), &outLength) != 1) {
215	        return HmacStatus::kCryptoError;
216	    }
217	    macLength = outLength;
218	    return HmacStatus::kSuccess;
219	}
220	
221	int runTag(int argc, char* argv[]) {
222	    // argv[1] is the "tag" subcommand name; option parsing starts at argv[2].
223	    std::map<std::string, std::string> opts;
224	    if (!parseValueOptions(
225	            argc, argv, "tag", kTagUsage,
226	            std::vector<std::string_view>{"--key-hex", "--file"}, opts)) {
227	        return 2;
228	    }
229	    if (!requireOption(opts, "tag", kTagUsage, "--key-hex") ||
230	        !requireOption(opts, "tag", kTagUsage, "--file")) {
231	        return 2;
232	    }
233	    const std::string& keyHex = opts["--key-hex"];
234	    const std::string& filePath = opts["--file"];
235	
236	    std::vector<unsigned char> key;
237	    if (!parseKey("tag", kTagUsage, keyHex, key)) {
238	        return 2;
239	    }
240	
241	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
242	    std::size_t macLength = 0;
243	    switch (hmacSha256File(key, filePath, mac, macLength)) {
244	        case HmacStatus::kReadError:
245	            std::cerr << "messagetag tag: error: failed to read file: "
246	                      << filePath << "\n";
247	            return 1;
248	        case HmacStatus::kCryptoError:
249	            std::cerr << "messagetag tag: error: HMAC-SHA-256 computation failed\n";
250	            return 1;
251	        case HmacStatus::kSuccess:
252	            break;
253	    }
254	
255	    std::cout << hexEncode(mac.data(), macLength) << '\n';
256	    return 0;
257	}
258	
259	// Compare two fixed-length byte strings without leaking the length of any
260	// matching prefix: the loop always touches every byte and accumulates all
261	// differences, so the running time does not depend on where (or whether)
262	// the inputs differ.
263	bool constantTimeEqual(const unsigned char* a, const unsigned char* b,
264	                       std::size_t length) {
265	    unsigned char diff = 0;
266	    for (std::size_t i = 0; i < length; ++i) {
267	        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
268	    }
269	    return diff == 0;
270	}
271	
272	int runVerify(int argc, char* argv[]) {
273	    // argv[1] is the "verify" subcommand name; parsing starts at argv[2].
274	    std::map<std::string, std::string> opts;
275	    if (!parseValueOptions(
276	            argc, argv, "verify", kVerifyUsage,
277	            std::vector<std::string_view>{"--key-hex", "--file", "--tag-hex"},
278	            opts)) {
279	        return 2;
280	    }
281	    if (!requireOption(opts, "verify", kVerifyUsage, "--key-hex") ||
282	        !requireOption(opts, "verify", kVerifyUsage, "--file") ||
283	        !requireOption(opts, "verify", kVerifyUsage, "--tag-hex")) {
284	        return 2;
285	    }
286	    const std::string& keyHex = opts["--key-hex"];
287	    const std::string& filePath = opts["--file"];
288	    const std::string& tagHex = opts["--tag-hex"];
289	
290	    // All input-format checks happen before the file is opened, so a
291	    // malformed key or tag is reported as a parameter error (exit 2) even
292	    // when the message file does not exist.
293	    std::vector<unsigned char> key;
294	    if (!parseKey("verify", kVerifyUsage, keyHex, key)) {
295	        return 2;
296	    }
297	
298	    // The supplied tag must decode to exactly 32 bytes (64 hex characters);
299	    // decodeHex already rejects empty input, odd length, non-hex characters
300	    // and whitespace, which also rules out a 0x prefix. The submitted tag is
301	    // deliberately not echoed back.
302	    std::vector<unsigned char> expected;
303	    if (!decodeHex(tagHex, expected) || expected.size() != kTagBytes) {
304	        std::cerr << "messagetag verify: error: invalid --tag-hex: expected "
305	                     "exactly 64 hexadecimal characters denoting 32 bytes "
306	                     "(0-9, a-f, A-F); empty, truncated or over-long values, "
307	                     "embedded whitespace and a 0x prefix are not accepted\n"
308	                  << kVerifyUsage;
309	        return 2;
310	    }
311	
312	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
313	    std::size_t macLength = 0;
314	    switch (hmacSha256File(key, filePath, mac, macLength)) {
315	        case HmacStatus::kReadError:
316	            // The partially read prefix must never be authenticated as if it
317	            // were the whole message.
318	            std::cerr << "messagetag verify: error: failed to read file: "
319	                      << filePath << "\n";
320	            return 1;
321	        case HmacStatus::kCryptoError:
322	            std::cerr << "messagetag verify: error: HMAC-SHA-256 "
323	                         "computation failed\n";
324	            return 1;
325	        case HmacStatus::kSuccess:
326	            break;
327	    }
328	
329	    if (macLength != kTagBytes ||
330	        !constantTimeEqual(mac.data(), expected.data(), kTagBytes)) {
331	        // State only that authentication failed; do not assign a cause (the
332	        // message, the key or the tag could each be the one that differs),
333	        // and never print the recomputed tag, a matched prefix or the key.
334	        std::cerr << "messagetag verify: error: authentication tag mismatch: "
335	                     "the supplied tag does not match the given key and file "
336	                     "content\n";
337	        return 3;
338	    }
339	
340	    std::cout << "OK\n";
341	    return 0;
342	}
343	
344	}  // namespace
345	
346	int main(int argc, char* argv[]) {
347	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
348	        std::cout << "messagetag 0.1.0\n";
349	        return 0;
350	    }
351	    if (argc >= 2 && std::string_view(argv[1]) == "tag") {
352	        return runTag(argc, argv);
353	    }
354	    if (argc >= 2 && std::string_view(argv[1]) == "verify") {
355	        return runVerify(argc, argv);
356	    }
357	    std::cerr << "Usage: messagetag --version\n"
358	              << "       messagetag tag --key-hex <hex-key> "
359	                 "--file <message-file>\n"
360	              << "       messagetag verify --key-hex <hex-key> "
361	                 "--file <message-file> --tag-hex <hex-tag>\n";
362	    return 2;
363	}
