108	// Parse options of the form "--name value" starting at argv[2]. On a usage
109	// problem (an unknown argument, or an option without a following value) a
110	// command-specific diagnostic and the usage line are written to stderr and
111	// this returns false; the caller then exits with code 2. On success the
112	// collected values are stored keyed by option name, and the caller checks
113	// which required options are present. Only the value-taking options named
114	// in `names` are accepted.
115	//
116	// An option's value is missing not only when nothing follows it, but also
117	// when the next token is itself one of this command's option names: in
118	// "--file --file" the second "--file" is another option, not a file name,
119	// so the first "--file" is reported as missing a value instead of
120	// consuming the option as its value. Only an exact match with a recognized
121	// option name triggers this; any other token (including one that merely
122	// starts with a dash, such as "--notes", and including an explicitly empty
123	// string) is taken as the value, so file paths with leading dashes stay
124	// usable and empty values keep their own distinct diagnostics.
125	bool parseValueOptions(int argc, char* argv[], std::string_view command,
126	                       std::string_view usage,
127	                       const std::vector<std::string_view>& names,
128	                       std::map<std::string, std::string>& values) {
129	    auto isOptionName = [&names](std::string_view arg) {
130	        for (std::string_view name : names) {
131	            if (arg == name) {
132	                return true;
133	            }
134	        }
135	        return false;
136	    };
137	    for (int i = 2; i < argc; ++i) {
138	        std::string arg(argv[i]);
139	        if (!isOptionName(arg)) {
140	            std::cerr << "messagetag " << command
141	                      << ": error: unknown argument '" << arg << "'\n"
142	                      << usage;
143	            return false;
144	        }
145	        // The diagnostic names only the option that lacks a value; the
146	        // following token (a recognized option name, or nothing at all) is
147	        // never spliced into the message, and neither is any key or tag
148	        // material supplied elsewhere on the command line.
149	        if (i + 1 >= argc || isOptionName(argv[i + 1])) {
150	            std::cerr << "messagetag " << command
151	                      << ": error: option '" << arg
152	                      << "' requires a value\n"
153	                      << usage;
154	            return false;
155	        }
156	        values[arg] = argv[++i];
157	    }
