189	// Stream the message file into HMAC-SHA-256 a fixed-size chunk at a time.
190	// The message is never stored whole: regardless of file length, only one
191	// 64 KiB read buffer is needed on top of the constant-size HMAC context.
192	//
193	// The bytes are not interpreted as text: the file is opened in binary mode,
194	// trailing newlines are kept, line endings are not converted and zero bytes
195	// are preserved. An empty file simply yields no Update calls, which
196	// authenticates the empty message.
197	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
198	
199	HmacStatus hmacSha256File(const std::vector<unsigned char>& key,
200	                          const std::string& path,
201	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
202	                          std::size_t& macLength) {
203	    HMAC_CTX* rawCtx = HMAC_CTX_new();
204	    if (rawCtx == nullptr) {
205	        return HmacStatus::kCryptoError;
206	    }
207	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx(rawCtx,
208	                                                            HMAC_CTX_free);
209	
210	    // Init with the key and SHA-256. HMAC_Init_ex performs the standard
211	    // RFC 2104 key normalization itself, so keys longer than the SHA-256
212	    // block size are hashed exactly as the standard requires; the resulting
213	    // tag is identical to the one-shot HMAC() interface on both OpenSSL
214	    // 1.1.1 and OpenSSL 3.x. The key is validated to be non-empty before
215	    // this is called, so key.data() is always valid.
216	    if (HMAC_Init_ex(ctx.get(), key.data(), static_cast<int>(key.size()),
217	                     EVP_sha256(), nullptr) != 1) {
218	        return HmacStatus::kCryptoError;
219	    }
220	
221	    std::ifstream in(path, std::ios::binary | std::ios::in);
222	    if (!in) {
223	        return HmacStatus::kReadError;
224	    }
225	
226	    std::array<char, 65536> buffer{};
227	    while (in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()))) {
228	        if (HMAC_Update(ctx.get(),
229	                        reinterpret_cast<const unsigned char*>(buffer.data()),
230	                        static_cast<std::size_t>(in.gcount())) != 1) {
231	            return HmacStatus::kCryptoError;
232	        }
233	    }
234	    // A read error (including one that happens after part of the message has
235	    // already been fed to HMAC) aborts authentication: Final is never called,
236	    // so no partial-message tag can be produced. EOF with a short final read
237	    // is normal and those remaining bytes must still participate.
238	    if (in.bad()) {
239	        return HmacStatus::kReadError;
240	    }
241	    if (in.gcount() > 0) {
242	        if (HMAC_Update(ctx.get(),
243	                        reinterpret_cast<const unsigned char*>(buffer.data()),
244	                        static_cast<std::size_t>(in.gcount())) != 1) {
245	            return HmacStatus::kCryptoError;
246	        }
247	    }
248	
249	    unsigned int outLength = 0;
250	    if (HMAC_Final(ctx.get(), mac.data(), &outLength) != 1) {
251	        return HmacStatus::kCryptoError;
252	    }
253	    macLength = outLength;
254	    return HmacStatus::kSuccess;
255	}
