270	    const std::string& filePath = opts["--file"];
271	
272	    std::vector<unsigned char> key;
273	    if (!parseKey("tag", kTagUsage, keyHex, key)) {
274	        return 2;
275	    }
276	
277	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
278	    std::size_t macLength = 0;
279	    switch (hmacSha256File(key, filePath, mac, macLength)) {
280	        case HmacStatus::kReadError:
281	            std::cerr << "messagetag tag: error: failed to read file: "
282	                      << filePath << "\n";
283	            return 1;
284	        case HmacStatus::kCryptoError:
285	            std::cerr << "messagetag tag: error: HMAC-SHA-256 computation failed\n";
286	            return 1;
287	        case HmacStatus::kSuccess:
288	            break;
289	    }
290	
291	    // Success is only complete once the full tag line (including the
292	    // stream buffer) has been delivered to standard output; a correct
293	    // computation alone does not justify exit 0.
294	    if (!writeResultLine(hexEncode(mac.data(), macLength))) {
295	        emitStdoutWriteFailure();
296	        return 1;
297	    }
298	    return 0;
299	}
