301	// Compare two fixed-length byte strings without leaking the length of any
302	// matching prefix: the loop always touches every byte and accumulates all
303	// differences, so the running time does not depend on where (or whether)
304	// the inputs differ.
305	bool constantTimeEqual(const unsigned char* a, const unsigned char* b,
306	                       std::size_t length) {
307	    unsigned char diff = 0;
308	    for (std::size_t i = 0; i < length; ++i) {
309	        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
310	    }
311	    return diff == 0;
312	}
