323	    if (!requireOption(opts, "verify", kVerifyUsage, "--key-hex") ||
324	        !requireOption(opts, "verify", kVerifyUsage, "--file") ||
325	        !requireOption(opts, "verify", kVerifyUsage, "--tag-hex")) {
326	        return 2;
327	    }
328	    const std::string& keyHex = opts["--key-hex"];
329	    const std::string& filePath = opts["--file"];
330	    const std::string& tagHex = opts["--tag-hex"];
331	
332	    // All input-format checks happen before the file is opened, so a
333	    // malformed key or tag is reported as a parameter error (exit 2) even
334	    // when the message file does not exist.
