345	    if (!decodeHex(tagHex, expected) || expected.size() != kTagBytes) {
346	        std::cerr << "messagetag verify: error: invalid --tag-hex: expected "
347	                     "exactly 64 hexadecimal characters denoting 32 bytes "
348	                     "(0-9, a-f, A-F); empty, truncated or over-long values, "
349	                     "embedded whitespace and a 0x prefix are not accepted\n"
350	                  << kVerifyUsage;
