// The low-level HMAC functions (HMAC_CTX_new/HMAC_Init_ex/HMAC_Update/
// HMAC_Final) are available in both OpenSSL 1.1.1 and OpenSSL 3.x.
// OpenSSL 3.x marks them deprecated in favour of the EVP_MAC interface
// (which 1.1.1 does not have); suppress those deprecation warnings so the
// portable interface builds cleanly on 3.x. The streaming Init/Update/
// Final form lets the message file be digested in fixed-size chunks
// instead of being held in memory all at once.
#define OPENSSL_SUPPRESS_DEPRECATED
#include <openssl/evp.h>
#include <openssl/hmac.h>

#include <array>
#include <cstddef>
#include <fstream>
#include <iostream>
#include <map>
#include <memory>
#include <string>
#include <string_view>
#include <vector>

#if defined(__unix__) || defined(__APPLE__)
#include <cerrno>
#include <csignal>
#endif

namespace {

constexpr std::string_view kTagUsage =
    "Usage: messagetag tag --key-hex <hex-key> --file <message-file>\n";

constexpr std::string_view kVerifyUsage =
    "Usage: messagetag verify --key-hex <hex-key> --file <message-file> "
    "--tag-hex <hex-tag>\n";

// SHA-256 HMAC tags are always 32 bytes / 64 hex characters.
constexpr std::size_t kTagBytes = 32;

// Decode hexadecimal into raw bytes: every two characters are one byte and
// leading zeros must be preserved (e.g. "0001" is two bytes, not the number
// 1). Only digits and a-f/A-F are accepted; empty input, odd length,
// whitespace and a 0x prefix are rejected.
bool decodeHex(std::string_view hex, std::vector<unsigned char>& bytes) {
    if (hex.empty() || hex.size() % 2 != 0) {
        return false;
    }
    auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    bytes.clear();
    bytes.reserve(hex.size() / 2);
    for (std::size_t i = 0; i < hex.size(); i += 2) {
        int hi = nibble(hex[i]);
        int lo = nibble(hex[i + 1]);
        if (hi < 0 || lo < 0) {
            return false;
        }
        bytes.push_back(static_cast<unsigned char>((hi << 4) | lo));
    }
    return true;
}

std::string hexEncode(const unsigned char* data, std::size_t length) {
    static constexpr char kHex[] = "0123456789abcdef";
    std::string out;
    out.resize(length * 2);
    for (std::size_t i = 0; i < length; ++i) {
        out[2 * i] = kHex[data[i] >> 4];
        out[2 * i + 1] = kHex[data[i] & 0x0F];
    }
    return out;
}

// Write the complete one-line success result (the 64-hex-char tag for
// `tag`, "OK" for `verify`) to standard output. A correct computation or a
// successful comparison is not success by itself: the whole line, including
// anything still held in the stream's user-level buffer, must actually have
// been handed to the operating system. The insertion and the explicit flush
// are therefore both checked; on failure no retry or second result line is
// attempted (some bytes may already have reached the recipient, and those
// remnants are never presented as a usable result) and the caller reports a
// single output-stage diagnostic and exits 1.
bool writeResultLine(std::string_view line) {
    std::cout << line << '\n';
    if (!std::cout.good()) {
        return false;
    }
    std::cout.flush();
    return !std::cout.fail() && !std::cout.bad();
}

// The single diagnostic for a failure that happened while delivering the
// result line: the destination ran out of space, reported a device error or
// closed the reading end of a pipe. It is deliberately distinct from the
// read, key-format and mismatch diagnostics, never names the message, key
// or tag, and carries no usage text or success hint. std::cerr is
// unit-buffered while stdio sync is enabled (the default here), so the one
// line reaches fd 2 immediately even though the process exits right away.
void emitStdoutWriteFailure() {
    std::cerr << "messagetag: error: failed to write result to standard "
                 "output\n";
    std::cerr.flush();
}

// Parse options of the form "--name value" starting at argv[2]. On a usage
